const voidRentalDocuments = `-- name: VoidRentalDocuments :many
UPDATE documents
SET status = 'void'
WHERE organization_id = $1
  AND rental_id = $2
  AND status <> 'void'
RETURNING uuid
`

type VoidRentalDocumentsParams struct {
	OrganizationID int64       `json:"organization_id"`
	RentalID       pgtype.Int8 `json:"rental_id"`
}

func (q *Queries) VoidRentalDocuments(ctx context.Context, arg VoidRentalDocumentsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, voidRentalDocuments, arg.OrganizationID, arg.RentalID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var uuid uuid.UUID
		if err := rows.Scan(&uuid); err != nil {
			return nil, err
		}
		items = append(items, uuid)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
